// Helpers to generate solid 3D extrusions via multiple shadows
const makeSolidShadow = (color: string, depth: number, s: number) => {
  let shadow = "";
  for (let i = 1; i <= depth; i++) {
    const offset = (i * s).toFixed(2);
    shadow += `${offset}px ${offset}px 0px ${color}${i === depth ? "" : ", "}`;
  }
  return shadow;
};

